package com.bookstore.service.impl; import com.bookstore.entity.Customer; import com.bookstore.exception.ResourceNotFoundException; import com.bookstore.repository.CustomerRepository; import com.bookstore.service.CustomerService; import org.springframework.stereotype.Service; import java.util.*; @Service public class CustomerServiceImpl implements CustomerService{ private final CustomerRepository repo; public CustomerServiceImpl(CustomerRepository repo){this.repo=repo;} public List<Customer> findAll(){return repo.findAll();} public Customer findById(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Customer not found: "+id));} public Customer save(Customer v){return repo.save(v);} public void delete(Long id){repo.delete(findById(id));} }